package com.vandorlabs.neoforge.gear;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;

/** Native strut cells displaced by a retracted world payload, separately owned from its inventory/content snapshot. */
final class NativeGearStoredSections {
    private final List<NativeGearSnapshot.Cell> cells;private final Map<BlockPos,NativeGearSnapshot.Cell> positions;
    NativeGearStoredSections(List<NativeGearSnapshot.Cell> cells){if(cells.isEmpty()||cells.size()>512)throw new IllegalArgumentException("Stored arm section count bound");this.cells=List.copyOf(cells);var map=new HashMap<BlockPos,NativeGearSnapshot.Cell>();long bytes=128;for(var cell:cells){if(!cell.section||map.putIfAbsent(cell.pos,cell)!=null)throw new IllegalArgumentException("Invalid stored arm section role/duplicate");bytes+=cell.bytes()+128;}if(bytes>NativeGearSnapshot.MAX_BYTES)throw new IllegalArgumentException("Stored arm section byte bound");positions=Map.copyOf(map);}
    List<NativeGearSnapshot.Cell> cells(){return cells;}NativeGearSnapshot.Cell at(BlockPos pos){return positions.get(pos);}int size(){return cells.size();}
    static boolean canStore(NativeGearEntity root,BlockPos pos){if(root.definition().kind!=NativeGearDefinition.Kind.EXTENDER||root.progress()!=0||!root.controller()||root.assembly().kind()!=com.vandorlabs.gear.core.GearTopology.FootKind.NONE||!root.members().contains(pos)||root.columns().stream().map(root.getBlockPos()::offset).anyMatch(pos::equals))return false;var member=NativeGearFormation.at(root.getLevel(),pos);return member!=null&&!member.inert()&&member.definition()==root.definition()&&root.getBlockPos().equals(member.owner())&&member.payload()==null&&!member.hasStoredSections();}
    static NativeGearSnapshot.Cell capture(NativeGearEntity root,BlockPos pos){if(!canStore(root,pos))throw new IllegalArgumentException("Arm section changed before native endpoint publication");var cell=NativeGearSnapshot.capture((ServerLevel)root.getLevel(),pos,true);return new NativeGearSnapshot.Cell(cell.pos,cell.state,cell.tile(),true);}
    static NativeGearStoredSections merge(NativeGearStoredSections previous,List<NativeGearSnapshot.Cell> additions){var list=new ArrayList<NativeGearSnapshot.Cell>();if(previous!=null)list.addAll(previous.cells);list.addAll(additions);return list.isEmpty()?null:new NativeGearStoredSections(list);}
    CompoundTag write(UUID owner){var tag=new CompoundTag();tag.putInt("Schema",1);tag.putUUID("Owner",owner);var list=new ListTag();for(var cell:cells)list.add(cell.write());tag.put("Cells",list);return tag;}
    static CompoundTag write(NativeGearStoredSections sections,UUID owner){return sections==null?new CompoundTag():sections.write(owner);}
    static NativeGearStoredSections read(HolderLookup.Provider registries,BlockPos root,UUID owner,Direction mount,NativeGearDefinition definition,CompoundTag tag){if(tag.isEmpty())return null;if(tag.sizeInBytes()>NativeGearSnapshot.MAX_BYTES||!tag.getAllKeys().equals(Set.of("Schema","Owner","Cells"))||!tag.contains("Schema",Tag.TAG_INT)||tag.getInt("Schema")!=1||!tag.hasUUID("Owner")||!tag.getUUID("Owner").equals(owner)||!(tag.get("Cells") instanceof ListTag list)||list.isEmpty()||list.size()>512||list.getElementType()!=Tag.TAG_COMPOUND)throw new IllegalArgumentException("Malformed stored arm section envelope");var cells=new ArrayList<NativeGearSnapshot.Cell>();for(var raw:list){var cell=NativeGearSnapshot.read(registries,(CompoundTag)raw,root);var data=cell.tile();if(!cell.section||cell.pos.equals(root)||data==null||!(cell.state.getBlock() instanceof NativeGearBlock block)||block.definition()!=definition||definition.kind!=NativeGearDefinition.Kind.EXTENDER||data.contains("NativeGearPayload")||data.contains("NativeGearStoredSections")||data.contains("ArmPayload")||data.contains("ArmStoredSections")||data.getBoolean("GearController"))throw new IllegalArgumentException("Invalid stored arm section ownership");var staged=NativeGearSnapshot.stage(registries,cell,true);if(!(staged instanceof NativeGearEntity tile)||tile.inert()||tile.mount()!=mount||!root.equals(tile.owner())||tile.payload()!=null||tile.hasStoredSections())throw new IllegalArgumentException("Stored arm section controller/mount identity");cells.add(cell);}return new NativeGearStoredSections(cells);}
}
